import test from 'node:test';
import assert from 'node:assert/strict';
import { fixture } from '../../splatoon3/tests/source-fixture.mjs';

// Two identical films: one whose FX camera always sees it (regenerated every tick, as before), one whose FX camera
// looks away (held back) and is only generated by the scene's pre-render hook for a camera that sees it.
test('an unseen film skips its shape rebuild and a rendering camera that sees it gets the exact current shape',async()=>{
  const f=await fixture({fullRuntime:true,productionComposition:true,extraExports:"export {FX} from './src/fx/fx.js';"});
  const {G,THREE}=f;
  const camera=(target)=>{const c=new THREE.PerspectiveCamera(50,16/9,.1,500);c.position.set(0,2,6);c.lookAt(target);c.updateMatrixWorld();return c;};
  const sees=camera(new THREE.Vector3(0,0,0)),away=camera(new THREE.Vector3(0,2,60));
  const actor=()=>({alive:true,isLocal:true,form:'squid',submerged:true,grounded:true,climbing:false,pos:new THREE.Vector3(),vel:new THREE.Vector3(0,0,8),groundN:new THREE.Vector3(0,1,0),color:new THREE.Color('#e4e900'),s3:{modifiers:{}}});
  const rigs=[sees,away].map(cam=>{const scene=new THREE.Scene(),fx=new f.FX(scene,{quality:'high'});return {cam,scene,fx,a:actor()};});
  const film=r=>r.fx.swimSurface.slots[0].mesh;
  const render=(r,cam)=>{r.scene.updateMatrixWorld();r.scene.onBeforeRender(null,r.scene,cam,null);};
  G.time=0;
  try{
    const tick=(turn=0)=>{G.time+=1/60;for(const r of rigs){G.actors=[r.a];r.a.vel.set(Math.sin(turn)*8,0,Math.cos(turn)*8);r.fx.wake(r.a.pos,r.a.vel,r.a.color,8,r.a.groundN,r.a);r.fx.update(1/60,r.cam);}};
    for(let n=0;n<30;n++)tick(n*.02);
    const [seen,unseen]=rigs.map(film);
    assert(seen.visible&&unseen.visible,'both films are live');
    const version=unseen.geometry.attributes.position.version;
    for(let n=0;n<30;n++){tick(.6+n*.03);render(rigs[1],away);}
    assert.equal(unseen.geometry.attributes.position.version,version,'no rebuild while every camera misses it');
    assert.notDeepEqual(Array.from(unseen.geometry.attributes.position.array),Array.from(seen.geometry.attributes.position.array),'held back');
    render(rigs[1],sees);
    for(const name of ['position','normal'])assert.deepEqual(Array.from(unseen.geometry.attributes[name].array),Array.from(seen.geometry.attributes[name].array),name+' equals the every-tick shape');
    assert.deepEqual(unseen.geometry.userData.filmHoles.map(v=>v.toArray()),seen.geometry.userData.filmHoles.map(v=>v.toArray()),'hole uniforms follow the shape');
    const v=unseen.geometry.attributes.position.version;render(rigs[1],sees);
    assert.equal(unseen.geometry.attributes.position.version,v,'one rebuild per tick, however many passes render it');
    // A film its FX camera sees is still rebuilt during the update itself.
    const before=seen.geometry.attributes.position.version;tick(1.5);
    assert(seen.geometry.attributes.position.version>before);
    // Lifecycle: cleared films drop pending work; disposal leaves the scene hook.
    rigs[1].fx.clear();render(rigs[1],sees);assert.equal(unseen.visible,false);
    const hook=Symbol.for('inkwave.swim-film.pre-render.v1');
    assert.equal(rigs[1].scene[hook].size,1);rigs[1].fx.dispose();assert.equal(rigs[1].scene[hook].size,0);
    render(rigs[1],sees);
  }finally{for(const r of rigs)r.fx.swimSurface&&r.fx.dispose();G.actors=[];}
});

test('the bounding sphere used for the visibility test contains every film shape',async()=>{
  const f=await fixture({fullRuntime:true,productionComposition:true,extraExports:"export {FX} from './src/fx/fx.js';"});
  const {G,THREE}=f;G.time=0;
  const scene=new THREE.Scene(),fx=new f.FX(scene,{quality:'high'});
  const a={alive:true,isLocal:true,form:'squid',submerged:true,grounded:true,climbing:false,pos:new THREE.Vector3(),vel:new THREE.Vector3(0,0,11.8),groundN:new THREE.Vector3(0,1,0),color:new THREE.Color('#e4e900'),s3:{modifiers:{}}};
  G.actors=[a];
  try{
    let worst=0,sphere;
    for(let n=0;n<600;n++){
      G.time+=1/60;const yaw=Math.sin(n*.37)*2.5,speed=2.5+9.3*(n%7)/6;a.vel.set(Math.sin(yaw)*speed,0,Math.cos(yaw)*speed);
      fx.wake(a.pos,a.vel,a.color,speed,a.groundN,a);fx.update(1/60);
      const g=fx.swimSurface.slots[0].mesh.geometry,p=g.attributes.position.array;sphere=g.boundingSphere;
      for(let i=0;i<p.length;i+=3)worst=Math.max(worst,Math.hypot(p[i]-sphere.center.x,p[i+1]-sphere.center.y,p[i+2]-sphere.center.z));
    }
    assert(worst>.5&&worst<sphere.radius*.75,`max vertex distance ${worst} inside r ${sphere.radius}`);
  }finally{fx.dispose();G.actors=[];}
});
